package com.collabspace.config; import lombok.RequiredArgsConstructor;import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.*; @Configuration @RequiredArgsConstructor public class WebMvcConfig implements WebMvcConfigurer {private final RateLimitInterceptor rateLimitInterceptor;public void addInterceptors(InterceptorRegistry r){r.addInterceptor(rateLimitInterceptor);}}